interface ExportApi {
    String export();
    default String mediaType() { return "text/plain"; }
    static boolean supported(String type) { return type.startsWith("text/"); }
}
class LegacyExporter implements ExportApi {
    public String export() { return "data"; }
}
public class InterfaceEvolutionDemo {
    public static void main(String[] args) { var e = new LegacyExporter(); System.out.println(e.export() + " " + e.mediaType() + " " + ExportApi.supported(e.mediaType())); }
}
